CREATE TABLE IF NOT EXISTS autonomy_intents(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),source_task TEXT NOT NULL,source_run_id TEXT NOT NULL REFERENCES runs(id),instance_id TEXT NOT NULL REFERENCES instances(id),round INTEGER NOT NULL,kind TEXT NOT NULL,request_key TEXT NOT NULL,fingerprint TEXT NOT NULL,target_task TEXT NOT NULL,generation INTEGER,body TEXT NOT NULL,state TEXT NOT NULL,error TEXT,result TEXT,created_at INTEGER NOT NULL,finished_at INTEGER,UNIQUE(source_run_id,request_key));
CREATE INDEX IF NOT EXISTS autonomy_intents_goal ON autonomy_intents(goal_id,state);
